<?php
declare(strict_types=1);
$registerEdit ??= null;
$registerPage ??= ['items'=>[], 'nextOffset'=>null];
$registerHistory ??= [];
$registerOffset ??= 0;
$closing = $accountingTab === 'closing';
$registerUrl = $taxUrl . '&tab=' . $accountingTab . '&year=' . $taxYear;
$showVoided = ($_GET['show_voided'] ?? '') === '1';
$registerListUrl = $registerUrl . ($showVoided ? '&show_voided=1' : '');
$recordKinds = array_filter(\SimpleStore\Accounting\TaxRegisterRepository::KINDS,
    static fn ($key) => $closing !== in_array($key, ['receivable','liability','asset'], true), ARRAY_FILTER_USE_KEY);
$draft = $registerEdit ?? ['opened_on' => $closing ? $taxYear . '-12-31' : $today, 'kind' => $closing ? 'inventory_stock' : 'receivable'];
if ($accountingError !== '' && ($_POST['action'] ?? '') === 'tax-save-record') $draft = array_replace($draft, $_POST);
$field = static fn (string $key, mixed $fallback = ''): string => is_scalar($draft[$key] ?? $fallback) ? (string) ($draft[$key] ?? $fallback) : '';
?>
<section class="panel-panel"><div class="panel-panel-head"><h2><?= $closing ? 'Inventura a uzávěrkové úpravy' : 'Pohledávky, dluhy a majetek' ?> · <?= (int) $taxYear ?></h2><a class="panel-button" href="<?= $escape($registerUrl . '&download=' . $accountingTab) ?>">Export CSV</a></div>
<?php if ($closing): ?><p>Ke konci roku zapiš zjištěný stav zásob, majetku, pohledávek a dluhů. Zásoby oceňuj podle daňových pravidel, nikoli prodejní cenou. Zboží nakupované jménem zákazníka není tvou vlastní zásobou.</p><p class="panel-help">Inventurní záznam sám nemění peněžní deník ani základ daně. Potřebný daňový dopad rozdílu, odpis či jinou úpravu vlož samostatně jako „Uzávěrka“ s odůvodněním. Pro rok s procentními výdaji nebo paušální daní nelze automaticky použít úpravy určené pro skutečné výdaje.</p>
  <dl class="panel-ledger-totals"><div><dt>Uzávěrkové úpravy příjmů</dt><dd><?= $taxMoney($taxAdjustments['income'] ?? 0) ?></dd></div><div><dt>Uzávěrkové úpravy výdajů</dt><dd><?= $taxMoney($taxAdjustments['expenses'] ?? 0) ?></dd></div></dl>
<?php else: ?><p>Sem patří i doklady mimo e-shop. U pohledávky a dluhu eviduj neuhrazenou částku; částečné úhrady zaznamenej opravou s odkazem na platbu. Zaplacení zapiš samostatně do peněžního deníku.</p><p class="panel-help">Kartu lze doplnit, uzavřít nebo znovu otevřít. Roční stav zachyť také v <a href="<?= $escape($taxUrl . '&tab=closing&year=' . $taxYear) ?>">inventuře</a>, aby pozdější úhrady nepřepsaly podklad uzávěrky. U majetku uveď do poznámky pořizovací cenu, zařazení, odpisy a zůstatkovou cenu podle svých podkladů.</p><?php endif; ?>
</section>
<section class="panel-panel" id="register-edit"><details <?= $registerEdit !== null || $accountingError !== '' ? 'open' : '' ?>><summary><?= $registerEdit !== null ? 'Upravit záznam #' . (int) $registerEdit['id'] : '+ Přidat záznam' ?></summary>
  <?php if ($registerEdit === null || $registerEdit['voided_at'] === null): ?>
  <form class="panel-form panel-evidence-form" method="post" action="<?= $escape($registerUrl . ($registerEdit !== null ? '&edit_record=' . (int) $registerEdit['id'] : '')) ?>">
    <input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><input type="hidden" name="action" value="tax-save-record"><input type="hidden" name="tab" value="<?= $accountingTab ?>"><input type="hidden" name="year" value="<?= (int) $taxYear ?>"><input type="hidden" name="id" value="<?= (int) ($registerEdit['id'] ?? 0) ?>"><input type="hidden" name="version" value="<?= $escape($field('version',1)) ?>"><input type="hidden" name="request_key" value="<?= $escape($field('request_key',bin2hex(random_bytes(16)))) ?>">
    <label>Druh<select name="kind"><?php foreach ($recordKinds as $key=>$label): ?><option value="<?= $key ?>" <?= $field('kind') === $key ? 'selected' : '' ?>><?= $escape($label) ?></option><?php endforeach; ?></select></label>
    <label><?= $closing ? 'Datum zjištění / úpravy' : 'Datum vzniku / pořízení' ?><input type="date" name="opened_on" value="<?= $escape($field('opened_on')) ?>" required></label>
    <label><?= $closing ? 'Skutečná hodnota / výše úpravy Kč' : 'Evidovaná hodnota / zbývá uhradit Kč' ?><input name="amount_czk" inputmode="decimal" value="<?= $escape($field('amount_czk')) ?>" required></label>
    <label class="panel-evidence-wide">Popis / identifikace položky<input name="description" maxlength="255" value="<?= $escape($field('description')) ?>" required></label>
    <label>Protistrana<input name="counterparty" maxlength="190" value="<?= $escape($field('counterparty')) ?>"></label><label>Doklad / reference<input name="reference" maxlength="100" value="<?= $escape($field('reference')) ?>"></label>
    <?php if ($closing): ?><label>Evidenční hodnota před inventurou Kč<input name="book_value_czk" inputmode="decimal" value="<?= $escape($field('book_value_czk','0')) ?>"></label><?php endif; ?>
    <label>Množství a jednotka · volitelné<input name="quantity" maxlength="40" placeholder="např. 12 ks" value="<?= $escape($field('quantity')) ?>"></label>
    <?php if (!$closing): ?><label>Datum uzavření / vyřazení · volitelné<input type="date" name="closed_on" value="<?= $escape($field('closed_on')) ?>"></label><?php endif; ?>
    <label class="panel-evidence-wide">Podklady, ocenění, odpisy, poznámka<textarea name="note" maxlength="4000" rows="3"><?= $escape($field('note')) ?></textarea></label>
    <?php if ($registerEdit !== null): ?><label class="panel-evidence-wide">Důvod opravy<input name="reason" maxlength="190" value="<?= $escape($field('reason')) ?>" required></label><?php endif; ?>
    <div class="panel-ledger-actions panel-evidence-wide"><button class="panel-button">Uložit záznam</button><?php if ($registerEdit !== null): ?><a href="<?= $escape($registerUrl) ?>">Zavřít úpravu</a><?php endif; ?></div>
  </form>
  <?php else: ?><p>Záznam je vyřazený. Původní údaje jsou v historii níže.</p><form class="panel-form" method="post" action="<?= $escape($registerUrl) ?>"><input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><input type="hidden" name="action" value="tax-restore-record"><input type="hidden" name="tab" value="<?= $accountingTab ?>"><input type="hidden" name="year" value="<?= (int) $taxYear ?>"><input type="hidden" name="id" value="<?= (int) $registerEdit['id'] ?>"><input type="hidden" name="version" value="<?= (int) $registerEdit['version'] ?>"><label>Důvod obnovení<input name="reason" maxlength="190" required></label><button class="panel-button">Obnovit záznam</button></form><?php endif; ?>
  <?php if ($registerEdit !== null && $registerEdit['voided_at'] === null): ?><details><summary>Vyřadit chybný záznam</summary><form class="panel-form" method="post" action="<?= $escape($registerUrl) ?>"><input type="hidden" name="csrf" value="<?= $escape($csrf) ?>"><input type="hidden" name="action" value="tax-void-record"><input type="hidden" name="tab" value="<?= $accountingTab ?>"><input type="hidden" name="year" value="<?= (int) $taxYear ?>"><input type="hidden" name="id" value="<?= (int) $registerEdit['id'] ?>"><input type="hidden" name="version" value="<?= (int) $registerEdit['version'] ?>"><label>Důvod<input name="reason" maxlength="190" required></label><button class="panel-button">Vyřadit a zachovat historii</button></form></details><?php endif; ?>
</details></section>
<section class="panel-panel"><p><a href="<?= $escape($registerUrl . ($showVoided ? '' : '&show_voided=1')) ?>"><?= $showVoided ? 'Skrýt vyřazené záznamy' : 'Zobrazit i vyřazené záznamy' ?></a></p><div class="panel-table-wrap"><table class="panel-table panel-ledger-table"><thead><tr><th>Druh / datum</th><th>Popis / protistrana</th><th>Doklad</th><th>Množství</th><th>Hodnota Kč</th><th><?= $closing ? 'Rozdíl inventury' : 'Uzavřeno' ?></th><th></th></tr></thead><tbody>
<?php foreach ($registerPage['items'] as $row): ?><tr><td><?= $escape($recordKinds[$row['kind']] ?? $row['kind']) ?><small><?= $escape($row['opened_on']) ?></small></td><td><strong><?= $escape($row['description']) ?></strong><?php if ($row['voided_at'] !== null): ?><small>VYŘAZENO</small><?php endif; ?><small><?= $escape($row['counterparty']) ?></small><?php if ($row['note'] !== null && $row['note'] !== ''): ?><details><summary>Poznámka</summary><p class="panel-preserve-lines"><?= $escape($row['note']) ?></p></details><?php endif; ?></td><td><?= $escape($row['reference']) ?></td><td><?= $escape($row['quantity']) ?></td><td class="panel-table-money"><?= $taxMoney($row['amount_czk']) ?></td><td><?= $closing ? (str_starts_with($row['kind'],'inventory_') ? $taxMoney(\SimpleStore\Accounting\TaxMoney::decimal(\SimpleStore\Accounting\TaxMoney::cents((string) $row['amount_czk'],true)-\SimpleStore\Accounting\TaxMoney::cents((string) $row['book_value_czk'],true))) : '—') : $escape($row['closed_on'] ?? 'Otevřeno') ?></td><td><a href="<?= $escape($registerUrl . '&edit_record=' . (int) $row['id'] . '#register-edit') ?>">Upravit</a></td></tr><?php endforeach; ?>
<?php if ($registerPage['items'] === []): ?><tr><td colspan="7">Zatím žádné záznamy v tomto roce.</td></tr><?php endif; ?></tbody></table></div>
<nav class="panel-ledger-actions" aria-label="Stránky evidence"><?php if ($registerOffset > 0): ?><a href="<?= $escape($registerListUrl . '&offset=' . max(0,$registerOffset-50)) ?>">← Předchozí</a><?php endif; ?><?php if ($registerPage['nextOffset'] !== null): ?><a href="<?= $escape($registerListUrl . '&offset=' . $registerPage['nextOffset']) ?>">Další →</a><?php endif; ?></nav></section>
<?php if ($registerHistory !== []): ?><details class="panel-panel"><summary>Historie tohoto záznamu</summary><?php foreach ($registerHistory as $change): ?><details><summary><?= $escape($change['created_at'] . ' UTC · ' . $change['reason']) ?> · správce #<?= (int) $change['admin_id'] ?></summary><div class="panel-audit-values"><pre><?= $escape(json_encode(json_decode($change['old_json'] ?? 'null',true), JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT)) ?></pre><pre><?= $escape(json_encode(json_decode($change['new_json'],true), JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT)) ?></pre></div></details><?php endforeach; ?></details><?php endif; ?>
